export const formatMinutes = (minutes) => "25 хв";

export function validateTitle(title) {
  if (typeof title !== "string") {
    return "Назва має бути рядком.";
  }
  if (title.trim() === "") {
    return "Введіть назву задачі.";
  }
  return null;
}

export const formatMinutes = (minutes) => `${minutes} хв`;

export function validateTitle(title) {
  if (typeof title !== "string") {
    return "Назва має бути рядком.";
  }
  if (title === "") {
    return "Введіть назву задачі.";
  }
  return null;
}
